    this.lobby.on('factionSelected', () => this.render());
    this.lobby.on('readyChanged', () => this.render());
    this.lobby.on('playerCountChanged', () => {
      this._autoPopulateLobby();
      this.render();
    });

    return new Promise(resolve => { this._startResolver = resolve; });
  }

